import"./chunk-5BEVYMCJ.js";var a={Settings:"Pode\u0161avanja",Profile:"Profil",Leaderboard:"Rang lista","Your profile":"Tvoj profil","Profile, XP and leaderboard":"Profil, XP i rang lista","Your name on the weekly board, or not":"Tvoje ime na nedeljnoj rang listi, ili ne","Weekly leaderboard":"Nedeljna rang lista","This week":"Ove nedelje","Earn more XP":"Osvoji vi\u0161e XP","How to climb":"Kako da napreduje\u0161","Top this week":"Najbolji ove nedelje","Day streak":"Dana zaredom","Total XP":"Ukupno XP",Level:"Nivo","XP this week":"XP ove nedelje","Join the leaderboard":"Pridru\u017Ei se rang listi","Display name":"Ime za prikaz","Try Plus for free":"Isprobajte Plus besplatno","Get Ocufuse Plus":"Nabavite Ocufuse Plus","Try {days} days free":"Isprobajte {days} dana besplatno","See plans":"Pogledajte planove","Every game, your full history and the Doctor Brief.":"Sve igre, cela istorija i Doctor Brief.","Hide for a week":"Sakrij na nedelju dana","Stay on track":"Ostani na putu","We'll send one reminder a day, at {time}, if you haven't taken today's eye photo yet. You can change the time or turn it off in Preferences.":"Posla\u0107emo ti jedan podsetnik dnevno, u {time}, ako jo\u0161 nisi napravio dana\u0161nju fotografiju o\u010Diju. Vreme mo\u017Ee\u0161 promeniti ili ga isklju\u010Diti u Pode\u0161avanjima.","Allow notifications":"Dozvoli obave\u0161tenja","Not now":"Ne sada","name@example.com":"ime@primer.com","Back to ocufuse.com":"Nazad na ocufuse.com",Website:"Sajt",Language:"Jezik",Soon:"Uskoro",Privacy:"Privatnost",Terms:"Uslovi",Help:"Pomo\u0107","Buy us a coffee":"\u010Casti nas kafom",Dismiss:"Zatvori","A little care for your eyes, every day":"Malo brige za tvoje o\u010Di, svaki dan","Play two-minute eye games, track how your eyes feel, and keep a private record you can share with your doctor.":"Igraj igre za o\u010Di od dva minuta, bele\u017Ei kako se tvoje o\u010Di ose\u0107aju i vodi privatan zapis koji mo\u017Ee\u0161 da podeli\u0161 sa lekarom.","Continue with email":"Nastavi sa emailom","Continue with Google":"Nastavi sa Google nalogom","Continue with Apple":"Nastavi sa Apple nalogom","Already have an account?":"Ve\u0107 ima\u0161 nalog?","Log in":"Prijavi se","Your records stay private to you.":"Tvoji zapisi ostaju privatni.","Ocufuse helps you track changes, not diagnose conditions.":"Ocufuse ti poma\u017Ee da prati\u0161 promene, a ne da postavlja\u0161 dijagnoze.","Check your email":"Proveri email","We sent a login link to {email}. Open it in this browser. It works once and expires after an hour.":"Poslali smo link za prijavu na {email}. Otvori ga u ovom pregleda\u010Du. Radi jednom i isti\u010De posle sat vremena.","Send the link again":"Po\u0161alji link ponovo","Use a password instead":"Koristi lozinku","Create your account":"Napravi nalog","Welcome back":"Dobro do\u0161ao nazad","Free, and it takes a minute.":"Besplatno, traje minut.","Log in to your Ocufuse account.":"Prijavi se na svoj Ocufuse nalog.","Choose a password, or get a login link instead.":"Izaberi lozinku ili dobij link za prijavu.","Enter your password, or get a login link instead.":"Unesi lozinku ili dobij link za prijavu.",or:"ili",Email:"Email","Enter an email address like name@example.com.":"Unesi email adresu kao ime@primer.com.",Change:"Promeni","First name (optional)":"Ime (opciono)","Create a password":"Napravi lozinku",Password:"Lozinka","Enter your password.":"Unesi lozinku.","Forgot password?":"Zaboravio si lozinku?","Create account":"Napravi nalog","Sign up with a login link":"Registruj se pomo\u0107u linka za prijavu","Email me a login link":"Po\u0161alji mi link za prijavu","No password needed: we email you a link that logs you in.":"Bez lozinke: \u0161aljemo ti email sa linkom koji te prijavljuje.","New to Ocufuse?":"Nov si na Ocufuse-u?","Create an account":"Napravi nalog","By creating an account you agree that Ocufuse stores your entries and photos in your private account so you can see them on any device. You can export or delete everything in Settings.":"Pravljenjem naloga prihvata\u0161 da Ocufuse \u010Duva tvoje unose i fotografije na tvom privatnom nalogu, kako bi ih video na bilo kom ure\u0111aju. Sve mo\u017Ee\u0161 da izveze\u0161 ili obri\u0161e\u0161 u Pode\u0161avanjima.","Log in with a link":"Prijavi se pomo\u0107u linka","Reset your password":"Resetuj lozinku","We will email you a link that logs you in. No password needed.":"Posla\u0107emo ti email sa linkom koji te prijavljuje. Bez lozinke.","We will email you a link to choose a new password. It works once, in this browser, for 15 minutes.":"Posla\u0107emo ti email sa linkom za izbor nove lozinke. Radi jednom, u ovom pregleda\u010Du, 15 minuta.","Enter a valid email address.":"Unesi ispravnu email adresu.","Send login link":"Po\u0161alji link za prijavu","Send reset link":"Po\u0161alji link za resetovanje","Choose a new password":"Izaberi novu lozinku","This changes your password on every device, including the iPhone app. Afterwards every device is logged out and you log in with the new password.":"Ovo menja lozinku na svim ure\u0111ajima, uklju\u010Duju\u0107i iPhone aplikaciju. Posle toga se svi ure\u0111aji odjavljuju i prijavljuje\u0161 se novom lozinkom.","New password":"Nova lozinka","Confirm new password":"Potvrdi novu lozinku","The passwords do not match.":"Lozinke se ne poklapaju.","Save new password":"Sa\u010Duvaj novu lozinku","Cancel and log out":"Otka\u017Ei i odjavi se","Use at least 10 characters with upper and lower case letters and a number. Longer is stronger.":"Koristi najmanje 10 znakova sa velikim i malim slovima i brojem. Du\u017Ea je ja\u010Da.","Too weak":"Previ\u0161e slaba",Weak:"Slaba",Fair:"Osrednja",Strong:"Jaka","Very strong":"Veoma jaka","You logged out successfully.":"Uspe\u0161no si se odjavio.","Your account and all of its data were deleted.":"Tvoj nalog i svi njegovi podaci su obrisani.","You were logged out. Log in again to see your data.":"Odjavljen si. Prijavi se ponovo da vidi\u0161 svoje podatke.","Your password was changed and every device was logged out. Log in with your new password.":"Lozinka je promenjena i svi ure\u0111aji su odjavljeni. Prijavi se novom lozinkom.","You were logged out after 30 minutes without activity, to keep your health records private. Log in again to continue.":"Odjavljen si posle 30 minuta neaktivnosti, da bi tvoji zdravstveni zapisi ostali privatni. Prijavi se ponovo da nastavi\u0161.","Check your email to confirm your account. Open the link in this browser. If you already have an account with this email, log in instead.":"Proveri email da potvrdi\u0161 nalog. Otvori link u ovom pregleda\u010Du. Ako ve\u0107 ima\u0161 nalog sa ovim emailom, prijavi se.","If there is an account for {email}, we sent a link to choose a new password. It works once, in this browser, for {min} minutes.":"Ako postoji nalog za {email}, poslali smo link za izbor nove lozinke. Radi jednom, u ovom pregleda\u010Du, {min} minuta.","Something went wrong. Please try again.":"Ne\u0161to nije u redu. Poku\u0161aj ponovo.","We could not check that this is a real person. Check your connection and try again.":"Nismo mogli da proverimo da si stvarna osoba. Proveri vezu i poku\u0161aj ponovo.","That email and password do not match. Check them and try again.":"Email i lozinka se ne poklapaju. Proveri ih i poku\u0161aj ponovo.","Confirm your email first. Open the link we sent you, then log in.":"Prvo potvrdi email. Otvori link koji smo ti poslali, pa se prijavi.","Too many tries from this network. Wait a few minutes and try again.":"Previ\u0161e poku\u0161aja sa ove mre\u017Ee. Sa\u010Dekaj nekoliko minuta i poku\u0161aj ponovo.","Too many emails were sent. Wait a minute and try again.":"Poslato je previ\u0161e emailova. Sa\u010Dekaj minut i poku\u0161aj ponovo.","Choose a password you have not used for Ocufuse before.":"Izaberi lozinku koju ranije nisi koristio za Ocufuse.","This link has expired. Ask for a new one.":"Ovaj link je istekao. Zatra\u017Ei novi.","This link did not work. It may have expired or been opened in another browser. Ask for a new one and open it in this browser.":"Ovaj link nije radio. Mo\u017Eda je istekao ili je otvoren u drugom pregleda\u010Du. Zatra\u017Ei novi i otvori ga u ovom pregleda\u010Du.","This link did not work. It may have expired. Ask for a new one.":"Ovaj link nije radio. Mo\u017Eda je istekao. Zatra\u017Ei novi.","You seem to be offline. Check your connection and try again.":"Izgleda da nisi na mre\u017Ei. Proveri vezu i poku\u0161aj ponovo.","This sign-in option is turned off on Ocufuse\u2019s server right now. Continue with email.":"Ova opcija prijave je trenutno isklju\u010Dena na Ocufuse serveru. Nastavi sa emailom.","The sign-in was cancelled or not allowed. Try again, or continue with email.":"Prijava je otkazana ili nije dozvoljena. Poku\u0161aj ponovo ili nastavi sa emailom.",Today:"Danas",Practice:"Ve\u017Ebanje",Learn:"U\u010Di",Progress:"Napredak",Care:"Nega",Notifications:"Obave\u0161tenja","Urgent help":"Hitna pomo\u0107","Keyboard shortcuts":"Pre\u010Dice na tastaturi","Profile & settings":"Profil i pode\u0161avanja","Log out":"Odjavi se","Expand sidebar":"Pro\u0161iri bo\u010Dnu traku","Collapse sidebar":"Skupi bo\u010Dnu traku","Shows all tabs":"Prikazuje sve sekcije","Log out of Ocufuse?":"Odjaviti se sa Ocufuse-a?","Your data stays in your account. Photos cached here are removed.":"Tvoji podaci ostaju na nalogu. Fotografije sa\u010Duvane ovde se uklanjaju.","Work when you are not typing in a field.":"Rade kada ne kuca\u0161 u polju.","Menus and section names for now":"Za sada meniji i nazivi sekcija","The same choice as on the sign-in screens.":"Isti izbor kao na ekranima za prijavu.",Preferences:"Postavke",Account:"Nalog","Personal information":"Li\u010Dni podaci","Name, date of birth, profile photo":"Ime, datum ro\u0111enja, profilna fotografija","Sign-in and security":"Prijava i bezbednost","Data & privacy":"Podaci i privatnost","Export, manage or delete your data":"Izvezi, upravljaj ili obri\u0161i svoje podatke","Invite friends":"Pozovi prijatelje","Share your link, earn XP":"Podeli svoj link, osvoji XP","Doctors & care contacts":"Lekari i kontakti za negu",Subscription:"Pretplata","Ocufuse Plus":"Ocufuse Plus",App:"Aplikacija","Language, notifications, goals, appearance":"Jezik, obave\u0161tenja, ciljevi, izgled","Help & support":"Pomo\u0107 i podr\u0161ka","Guides, urgent help and privacy policy":"Vodi\u010Di, hitna pomo\u0107 i politika privatnosti","About Ocufuse":"O Ocufuse-u","Level and quests":"Nivo i misije","Logs out on this device. Your data stays in your account.":"Odjavljuje te na ovom ure\u0111aju. Tvoji podaci ostaju na nalogu."};export{a as default};
